/**
 * API Contract Validator
 *
 * Validates live API responses against the OpenAPI (Swagger) contract that the
 * NestJS app generates, and reports contract drift between documentation and
 * implementation.
 *
 * What it does:
 *   1. Loads the OpenAPI spec generated by `@nestjs/swagger` — either from the
 *      running app (`GET /api/openapi.json`, the default) or from an exported
 *      JSON file.
 *   2. Builds a test request for every safe (GET by default) operation whose
 *      required parameters can be resolved from `--param`, spec examples,
 *      defaults or enums.
 *   3. Sends the requests and validates each response's status code and JSON
 *      body against the documented response schema.
 *   4. Prints a drift report (optionally written to JSON) and exits non-zero
 *      when drift is detected, so it can gate CI.
 *
 * Drift that is detected:
 *   - undocumented-status    response status code not declared in the spec (error)
 *   - type-mismatch          value type differs from the schema (error)
 *   - missing-required       a required property is absent (error)
 *   - enum-mismatch          value is not one of the documented enum values (error)
 *   - format-mismatch        string doesn't match a documented format (error)
 *   - no-matching-variant    no oneOf/anyOf branch matches (error)
 *   - invalid-json           a JSON schema is documented but the body isn't JSON (error)
 *   - undocumented-property  response contains a property absent from the schema (warning)
 *   - undocumented-body      a body was returned for a response with no schema (warning)
 *
 * Usage:
 *   npx ts-node api-extensions/scripts/validate-api-contract.ts [options]
 *
 * Options:
 *   --base-url <url>      API origin (default: $API_BASE_URL or http://localhost:3000)
 *   --spec <url|file>     OpenAPI source (default: <base-url>/api/openapi.json)
 *   --token <jwt>         Bearer token for secured endpoints (default: $API_TOKEN)
 *   --api-key <key>       API key sent as `api-key` header (default: $API_KEY)
 *   --param <name=value>  Value for a path/query parameter (repeatable)
 *   --include <regex>     Only test paths matching the regex
 *   --exclude <regex>     Skip paths matching the regex
 *   --methods <list>      Comma-separated HTTP methods to test (default: GET)
 *   --envelope <mode>     auto | none — unwrap the `{ success, data }` envelope
 *                         added by ResponseFormatInterceptor (default: auto)
 *   --strict              Treat warnings (e.g. undocumented properties) as drift
 *   --timeout <ms>        Per-request timeout (default: 10000)
 *   --report <file>       Write the full JSON report to a file
 *
 * Exit codes:
 *   0  no drift detected
 *   1  contract drift detected
 *   2  fatal error (spec could not be loaded, invalid arguments, ...)
 */

import * as fs from 'fs';
import * as path from 'path';

// ---------------------------------------------------------------------------
// OpenAPI types (the subset this script relies on)
// ---------------------------------------------------------------------------

export interface SchemaObject {
  $ref?: string;
  type?: string | string[];
  format?: string;
  nullable?: boolean;
  enum?: unknown[];
  properties?: Record<string, SchemaObject>;
  required?: string[];
  additionalProperties?: boolean | SchemaObject;
  items?: SchemaObject;
  allOf?: SchemaObject[];
  oneOf?: SchemaObject[];
  anyOf?: SchemaObject[];
  example?: unknown;
  default?: unknown;
  minimum?: number;
  maximum?: number;
}

export interface ParameterObject {
  $ref?: string;
  name: string;
  in: 'path' | 'query' | 'header' | 'cookie';
  required?: boolean;
  schema?: SchemaObject;
  example?: unknown;
}

export interface MediaTypeObject {
  schema?: SchemaObject;
}

export interface ResponseObject {
  $ref?: string;
  description?: string;
  content?: Record<string, MediaTypeObject>;
}

export interface OperationObject {
  operationId?: string;
  parameters?: ParameterObject[];
  responses?: Record<string, ResponseObject>;
  security?: Array<Record<string, string[]>>;
  deprecated?: boolean;
}

export type PathItemObject = Partial<Record<HttpMethod, OperationObject>> & {
  parameters?: ParameterObject[];
};

export interface OpenAPIDocument {
  openapi?: string;
  swagger?: string;
  paths: Record<string, PathItemObject>;
  components?: {
    schemas?: Record<string, SchemaObject>;
    responses?: Record<string, ResponseObject>;
    parameters?: Record<string, ParameterObject>;
  };
  security?: Array<Record<string, string[]>>;
}

export const HTTP_METHODS = ['get', 'head', 'post', 'put', 'patch', 'delete', 'options'] as const;
export type HttpMethod = (typeof HTTP_METHODS)[number];

// ---------------------------------------------------------------------------
// Report types
// ---------------------------------------------------------------------------

export type IssueKind =
  | 'undocumented-status'
  | 'type-mismatch'
  | 'missing-required'
  | 'enum-mismatch'
  | 'format-mismatch'
  | 'no-matching-variant'
  | 'invalid-json'
  | 'undocumented-property'
  | 'undocumented-body'
  | 'request-failed';

export type IssueSeverity = 'error' | 'warning';

export interface ContractIssue {
  kind: IssueKind;
  severity: IssueSeverity;
  /** JSON-path-like location inside the response body, e.g. `$.data[0].id`. */
  path: string;
  message: string;
}

export interface TestCase {
  method: HttpMethod;
  /** Path template as it appears in the spec, e.g. `/api/v1/properties/{id}`. */
  pathTemplate: string;
  /** Concrete path with parameters substituted, including the query string. */
  url: string;
  operation: OperationObject;
  requiresAuth: boolean;
}

export interface SkippedOperation {
  method: HttpMethod;
  pathTemplate: string;
  reason: string;
}

export interface EndpointResult {
  method: string;
  path: string;
  url: string;
  status: number | null;
  durationMs: number;
  issues: ContractIssue[];
}

export interface ContractReport {
  generatedAt: string;
  specSource: string;
  baseUrl: string;
  strict: boolean;
  summary: {
    tested: number;
    passed: number;
    drifted: number;
    skipped: number;
    errors: number;
    warnings: number;
  };
  results: EndpointResult[];
  skipped: SkippedOperation[];
}

// ---------------------------------------------------------------------------
// $ref resolution
// ---------------------------------------------------------------------------

/** Resolve a local JSON pointer such as `#/components/schemas/UserDto`. */
export function resolvePointer(spec: OpenAPIDocument, ref: string): unknown {
  if (!ref.startsWith('#/')) {
    throw new Error(`Only local $ref values are supported (got "${ref}")`);
  }
  const segments = ref
    .slice(2)
    .split('/')
    .map((segment) => segment.replace(/~1/g, '/').replace(/~0/g, '~'));

  let current: unknown = spec;
  for (const segment of segments) {
    if (current === null || typeof current !== 'object' || !(segment in current)) {
      throw new Error(`Unresolvable $ref "${ref}"`);
    }
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

/** Follow `$ref` chains until a concrete object is reached. */
export function deref<T extends { $ref?: string }>(spec: OpenAPIDocument, value: T): T {
  let current = value;
  const seen = new Set<string>();
  while (current && current.$ref) {
    if (seen.has(current.$ref)) {
      throw new Error(`Circular $ref detected at "${current.$ref}"`);
    }
    seen.add(current.$ref);
    current = resolvePointer(spec, current.$ref) as T;
  }
  return current;
}

// ---------------------------------------------------------------------------
// Schema validation
// ---------------------------------------------------------------------------

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function describeType(value: unknown): string {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  if (typeof value === 'number' && Number.isInteger(value)) return 'integer';
  return typeof value;
}

function matchesType(value: unknown, type: string): boolean {
  switch (type) {
    case 'null':
      return value === null;
    case 'string':
      return typeof value === 'string';
    case 'boolean':
      return typeof value === 'boolean';
    case 'integer':
      return typeof value === 'number' && Number.isInteger(value);
    case 'number':
      return typeof value === 'number' && Number.isFinite(value);
    case 'array':
      return Array.isArray(value);
    case 'object':
      return value !== null && typeof value === 'object' && !Array.isArray(value);
    default:
      return true;
  }
}

function checkFormat(value: string, format: string): boolean {
  switch (format) {
    case 'date-time':
      return !Number.isNaN(Date.parse(value)) && value.includes('T');
    case 'date':
      return DATE_PATTERN.test(value) && !Number.isNaN(Date.parse(value));
    case 'uuid':
      return UUID_PATTERN.test(value);
    case 'email':
      return EMAIL_PATTERN.test(value);
    case 'uri':
    case 'url':
      try {
        new URL(value);
        return true;
      } catch {
        return false;
      }
    default:
      // Unknown/custom formats (e.g. "decimal", "password") are not enforced.
      return true;
  }
}

export interface ValidateOptions {
  /** Report response properties that are not described by the schema. */
  reportUndocumented: boolean;
  /**
   * Internal: location at which undocumented-property checks are skipped. Used for allOf
   * members, whose combined property set is checked once by the parent schema.
   */
  suppressUndocumentedAt?: string;
}

/** Collect the names of all properties declared by a schema, including allOf members. */
function collectDeclaredProperties(
  spec: OpenAPIDocument,
  schema: SchemaObject,
  seen: Set<SchemaObject> = new Set(),
): { names: Set<string>; open: boolean } {
  const resolved = deref(spec, schema);
  const names = new Set<string>();
  if (seen.has(resolved)) return { names, open: false };
  seen.add(resolved);

  let open =
    resolved.additionalProperties === true || typeof resolved.additionalProperties === 'object';
  for (const name of Object.keys(resolved.properties ?? {})) names.add(name);

  for (const member of resolved.allOf ?? []) {
    const nested = collectDeclaredProperties(spec, member, seen);
    nested.names.forEach((name) => names.add(name));
    open = open || nested.open;
  }
  // A plain `type: object` with no declared properties is a free-form object.
  if (
    !resolved.properties &&
    !resolved.allOf &&
    !resolved.oneOf &&
    !resolved.anyOf &&
    resolved.additionalProperties === undefined
  ) {
    open = true;
  }
  return { names, open };
}

/**
 * Validate a value against an OpenAPI schema. Supports $ref, type (incl.
 * OpenAPI 3.1 type arrays), nullable, enum, format, properties, required,
 * additionalProperties, items, allOf, oneOf and anyOf.
 */
export function validateAgainstSchema(
  spec: OpenAPIDocument,
  value: unknown,
  rawSchema: SchemaObject,
  location = '$',
  options: ValidateOptions = { reportUndocumented: true },
): ContractIssue[] {
  const schema = deref(spec, rawSchema);
  const issues: ContractIssue[] = [];

  const declaredTypes = schema.type === undefined ? [] : ([] as string[]).concat(schema.type);
  const nullable = schema.nullable === true || declaredTypes.includes('null');

  if (value === null) {
    // Composite schemas may allow null through one of their branches.
    if (
      nullable ||
      (declaredTypes.length === 0 && !schema.allOf && !schema.oneOf && !schema.anyOf)
    ) {
      return issues;
    }
    if (!schema.oneOf && !schema.anyOf) {
      issues.push({
        kind: 'type-mismatch',
        severity: 'error',
        path: location,
        message: `expected ${declaredTypes.join(' | ') || 'non-null value'} but got null`,
      });
      return issues;
    }
  }

  // --- composition -------------------------------------------------------
  if (schema.allOf) {
    for (const member of schema.allOf) {
      issues.push(
        ...validateAgainstSchema(spec, value, member, location, {
          ...options,
          suppressUndocumentedAt: location,
        }),
      );
    }
  }

  for (const keyword of ['oneOf', 'anyOf'] as const) {
    const variants = schema[keyword];
    if (!variants) continue;
    const attempts = variants.map((variant) =>
      validateAgainstSchema(spec, value, variant, location, options).filter(
        (issue) => issue.severity === 'error',
      ),
    );
    const matches = attempts.filter((attempt) => attempt.length === 0).length;
    if (matches === 0) {
      issues.push({
        kind: 'no-matching-variant',
        severity: 'error',
        path: location,
        message: `value does not match any ${keyword} variant (${variants.length} tried)`,
      });
    }
  }

  // --- type --------------------------------------------------------------
  const nonNullTypes = declaredTypes.filter((type) => type !== 'null');
  if (nonNullTypes.length > 0 && !nonNullTypes.some((type) => matchesType(value, type))) {
    issues.push({
      kind: 'type-mismatch',
      severity: 'error',
      path: location,
      message: `expected ${nonNullTypes.join(' | ')} but got ${describeType(value)}`,
    });
    return issues;
  }

  // --- enum / format -----------------------------------------------------
  if (schema.enum && !schema.enum.some((allowed) => allowed === value)) {
    issues.push({
      kind: 'enum-mismatch',
      severity: 'error',
      path: location,
      message: `value ${JSON.stringify(value)} is not one of ${JSON.stringify(schema.enum)}`,
    });
  }

  if (typeof value === 'string' && schema.format && !checkFormat(value, schema.format)) {
    issues.push({
      kind: 'format-mismatch',
      severity: 'error',
      path: location,
      message: `value ${JSON.stringify(value)} is not a valid ${schema.format}`,
    });
  }

  // --- arrays ------------------------------------------------------------
  if (Array.isArray(value) && schema.items) {
    value.forEach((item, index) => {
      issues.push(
        ...validateAgainstSchema(
          spec,
          item,
          schema.items as SchemaObject,
          `${location}[${index}]`,
          options,
        ),
      );
    });
  }

  // --- objects -----------------------------------------------------------
  if (matchesType(value, 'object')) {
    const record = value as Record<string, unknown>;
    const properties = schema.properties ?? {};

    for (const name of schema.required ?? []) {
      if (!(name in record) || record[name] === undefined) {
        issues.push({
          kind: 'missing-required',
          severity: 'error',
          path: `${location}.${name}`,
          message: `required property "${name}" is missing`,
        });
      }
    }

    for (const [name, propertySchema] of Object.entries(properties)) {
      if (name in record && record[name] !== undefined) {
        issues.push(
          ...validateAgainstSchema(
            spec,
            record[name],
            propertySchema,
            `${location}.${name}`,
            options,
          ),
        );
      }
    }

    const additional = schema.additionalProperties;
    if (typeof additional === 'object') {
      for (const [name, propertyValue] of Object.entries(record)) {
        if (!(name in properties)) {
          issues.push(
            ...validateAgainstSchema(
              spec,
              propertyValue,
              additional,
              `${location}.${name}`,
              options,
            ),
          );
        }
      }
    }

    if (
      options.reportUndocumented &&
      options.suppressUndocumentedAt !== location &&
      !schema.oneOf &&
      !schema.anyOf
    ) {
      const declared = collectDeclaredProperties(spec, schema);
      if (!declared.open) {
        for (const name of Object.keys(record)) {
          if (!declared.names.has(name)) {
            issues.push({
              kind: 'undocumented-property',
              severity: 'warning',
              path: `${location}.${name}`,
              message: `property "${name}" is returned but not documented`,
            });
          }
        }
      }
    }
  }

  return issues;
}

// ---------------------------------------------------------------------------
// Response validation
// ---------------------------------------------------------------------------

/** Pick the documented response for a status: exact code, then `2XX`-style range, then `default`. */
export function findResponseSpec(
  spec: OpenAPIDocument,
  operation: OperationObject,
  status: number,
): ResponseObject | undefined {
  const responses = operation.responses ?? {};
  const candidate =
    responses[String(status)] ?? responses[`${String(status)[0]}XX`] ?? responses.default;
  return candidate ? deref(spec, candidate) : undefined;
}

function findJsonSchema(response: ResponseObject): SchemaObject | undefined {
  const content = response.content ?? {};
  const mediaType =
    content['application/json'] ??
    Object.entries(content).find(([type]) => type.includes('json'))?.[1];
  return mediaType?.schema;
}

export type EnvelopeMode = 'auto' | 'none';

/**
 * ResponseFormatInterceptor wraps successful payloads as `{ success, data, meta, timestamp }`
 * while most DTOs document only the inner payload. In `auto` mode, unwrap the envelope unless
 * the documented schema itself describes it.
 */
export function unwrapEnvelope(
  spec: OpenAPIDocument,
  body: unknown,
  schema: SchemaObject,
  mode: EnvelopeMode,
): { value: unknown; location: string } {
  if (mode === 'none' || !matchesType(body, 'object')) return { value: body, location: '$' };
  const record = body as Record<string, unknown>;
  if (typeof record.success !== 'boolean' || !('data' in record)) {
    return { value: body, location: '$' };
  }
  const declared = collectDeclaredProperties(spec, schema);
  if (declared.names.has('success') || declared.names.has('data')) {
    return { value: body, location: '$' };
  }
  return { value: record.data, location: '$.data' };
}

export interface ResponseInput {
  status: number;
  contentType: string;
  rawBody: string;
}

export function validateResponse(
  spec: OpenAPIDocument,
  operation: OperationObject,
  response: ResponseInput,
  envelope: EnvelopeMode = 'auto',
): ContractIssue[] {
  const responseSpec = findResponseSpec(spec, operation, response.status);
  if (!responseSpec) {
    const documented = Object.keys(operation.responses ?? {}).join(', ') || 'none';
    return [
      {
        kind: 'undocumented-status',
        severity: 'error',
        path: '$',
        message: `status ${response.status} is not documented (documented: ${documented})`,
      },
    ];
  }

  const schema = findJsonSchema(responseSpec);
  const hasBody = response.rawBody.trim().length > 0;

  if (!schema) {
    return hasBody
      ? [
          {
            kind: 'undocumented-body',
            severity: 'warning',
            path: '$',
            message: `status ${response.status} returned a body but no response schema is documented`,
          },
        ]
      : [];
  }

  let body: unknown;
  try {
    body = JSON.parse(response.rawBody);
  } catch {
    return [
      {
        kind: 'invalid-json',
        severity: 'error',
        path: '$',
        message: `expected a JSON body (content-type: ${response.contentType || 'n/a'})`,
      },
    ];
  }

  const { value, location } = unwrapEnvelope(spec, body, schema, envelope);
  return validateAgainstSchema(spec, value, schema, location);
}

// ---------------------------------------------------------------------------
// Test case generation
// ---------------------------------------------------------------------------

function sampleParameterValue(
  spec: OpenAPIDocument,
  parameter: ParameterObject,
): string | undefined {
  if (parameter.example !== undefined) return String(parameter.example);
  if (!parameter.schema) return undefined;
  const schema = deref(spec, parameter.schema);
  if (schema.example !== undefined) return String(schema.example);
  if (schema.default !== undefined) return String(schema.default);
  if (schema.enum && schema.enum.length > 0) return String(schema.enum[0]);
  return undefined;
}

export interface BuildOptions {
  methods: HttpMethod[];
  params: Record<string, string>;
  include?: RegExp;
  exclude?: RegExp;
}

export function buildTestCases(
  spec: OpenAPIDocument,
  options: BuildOptions,
): { cases: TestCase[]; skipped: SkippedOperation[] } {
  const cases: TestCase[] = [];
  const skipped: SkippedOperation[] = [];

  for (const [pathTemplate, pathItem] of Object.entries(spec.paths ?? {})) {
    if (options.include && !options.include.test(pathTemplate)) continue;
    if (options.exclude && options.exclude.test(pathTemplate)) continue;

    for (const method of HTTP_METHODS) {
      const operation = pathItem[method];
      if (!operation) continue;
      if (!options.methods.includes(method)) {
        skipped.push({
          method,
          pathTemplate,
          reason: `method ${method.toUpperCase()} not selected`,
        });
        continue;
      }

      // Operation-level parameters override path-level ones with the same name + location.
      const parameters = new Map<string, ParameterObject>();
      for (const raw of [...(pathItem.parameters ?? []), ...(operation.parameters ?? [])]) {
        const parameter = deref(spec, raw);
        parameters.set(`${parameter.in}:${parameter.name}`, parameter);
      }

      let url = pathTemplate;
      const query = new URLSearchParams();
      const unresolved: string[] = [];

      for (const parameter of parameters.values()) {
        if (parameter.in !== 'path' && parameter.in !== 'query') continue;
        const value = options.params[parameter.name] ?? sampleParameterValue(spec, parameter);
        const required = parameter.in === 'path' || parameter.required === true;

        if (value === undefined) {
          if (required) unresolved.push(`${parameter.in}:${parameter.name}`);
          continue;
        }
        if (parameter.in === 'path') {
          url = url.split(`{${parameter.name}}`).join(encodeURIComponent(value));
        } else {
          query.set(parameter.name, value);
        }
      }

      // Templates without a matching parameter definition are also unresolved.
      for (const match of url.matchAll(/\{([^}]+)\}/g)) {
        const name = match[1];
        const value = options.params[name];
        if (value === undefined) {
          if (!unresolved.includes(`path:${name}`)) unresolved.push(`path:${name}`);
        } else {
          url = url.split(`{${name}}`).join(encodeURIComponent(value));
        }
      }

      if (unresolved.length > 0) {
        skipped.push({
          method,
          pathTemplate,
          reason: `unresolved required parameters: ${unresolved.join(', ')} (pass --param name=value)`,
        });
        continue;
      }

      const queryString = query.toString();
      const security = operation.security ?? spec.security ?? [];
      cases.push({
        method,
        pathTemplate,
        url: queryString ? `${url}?${queryString}` : url,
        operation,
        requiresAuth: security.some((requirement) => Object.keys(requirement).length > 0),
      });
    }
  }

  return { cases, skipped };
}

// ---------------------------------------------------------------------------
// Execution
// ---------------------------------------------------------------------------

export interface RunOptions extends BuildOptions {
  baseUrl: string;
  specSource: string;
  token?: string;
  apiKey?: string;
  envelope: EnvelopeMode;
  strict: boolean;
  timeoutMs: number;
}

export type FetchLike = (url: string, init: RequestInit) => Promise<Response>;

export async function loadSpec(
  source: string,
  fetchImpl: FetchLike = fetch,
): Promise<OpenAPIDocument> {
  let raw: string;
  if (/^https?:\/\//i.test(source)) {
    const response = await fetchImpl(source, { headers: { accept: 'application/json' } });
    if (!response.ok) {
      throw new Error(`Failed to fetch OpenAPI spec from ${source}: HTTP ${response.status}`);
    }
    raw = await response.text();
  } else {
    raw = fs.readFileSync(path.resolve(source), 'utf8');
  }

  const spec = JSON.parse(raw) as OpenAPIDocument;
  if (!spec || typeof spec !== 'object' || typeof spec.paths !== 'object') {
    throw new Error(`"${source}" is not a valid OpenAPI document (missing "paths")`);
  }
  return spec;
}

export async function runContractValidation(
  spec: OpenAPIDocument,
  options: RunOptions,
  fetchImpl: FetchLike = fetch,
): Promise<ContractReport> {
  const { cases, skipped } = buildTestCases(spec, options);
  const results: EndpointResult[] = [];

  for (const testCase of cases) {
    const headers: Record<string, string> = { accept: 'application/json' };
    if (options.token) headers.authorization = `Bearer ${options.token}`;
    if (options.apiKey) headers['api-key'] = options.apiKey;

    if (testCase.requiresAuth && !options.token && !options.apiKey) {
      skipped.push({
        method: testCase.method,
        pathTemplate: testCase.pathTemplate,
        reason: 'requires authentication (pass --token or --api-key)',
      });
      continue;
    }

    const url = `${options.baseUrl.replace(/\/$/, '')}${testCase.url}`;
    const started = Date.now();
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), options.timeoutMs);

    try {
      const response = await fetchImpl(url, {
        method: testCase.method.toUpperCase(),
        headers,
        signal: controller.signal,
      });
      const rawBody = testCase.method === 'head' ? '' : await response.text();
      results.push({
        method: testCase.method.toUpperCase(),
        path: testCase.pathTemplate,
        url,
        status: response.status,
        durationMs: Date.now() - started,
        issues: validateResponse(
          spec,
          testCase.operation,
          {
            status: response.status,
            contentType: response.headers.get('content-type') ?? '',
            rawBody,
          },
          options.envelope,
        ),
      });
    } catch (error) {
      results.push({
        method: testCase.method.toUpperCase(),
        path: testCase.pathTemplate,
        url,
        status: null,
        durationMs: Date.now() - started,
        issues: [
          {
            kind: 'request-failed',
            severity: 'error',
            path: '$',
            message: error instanceof Error ? error.message : String(error),
          },
        ],
      });
    } finally {
      clearTimeout(timer);
    }
  }

  const isDrift = (issue: ContractIssue) => issue.severity === 'error' || options.strict;
  const drifted = results.filter((result) => result.issues.some(isDrift)).length;
  const allIssues = results.flatMap((result) => result.issues);

  return {
    generatedAt: new Date().toISOString(),
    specSource: options.specSource,
    baseUrl: options.baseUrl,
    strict: options.strict,
    summary: {
      tested: results.length,
      passed: results.length - drifted,
      drifted,
      skipped: skipped.length,
      errors: allIssues.filter((issue) => issue.severity === 'error').length,
      warnings: allIssues.filter((issue) => issue.severity === 'warning').length,
    },
    results,
    skipped,
  };
}

export function formatReport(report: ContractReport): string {
  const lines: string[] = ['', 'API Contract Validation', '======================='];
  lines.push(`Spec:     ${report.specSource}`);
  lines.push(`Base URL: ${report.baseUrl}`);
  lines.push('');

  for (const result of report.results) {
    const errors = result.issues.filter((issue) => issue.severity === 'error');
    const warnings = result.issues.filter((issue) => issue.severity === 'warning');
    const drifted = errors.length > 0 || (report.strict && warnings.length > 0);
    const marker = drifted ? 'DRIFT' : warnings.length > 0 ? 'WARN ' : 'OK   ';
    lines.push(
      `[${marker}] ${result.method} ${result.path} -> ${result.status ?? 'ERR'} (${result.durationMs}ms)`,
    );
    for (const issue of result.issues) {
      lines.push(
        `         ${issue.severity === 'error' ? '✗' : '!'} ${issue.kind} at ${issue.path}: ${issue.message}`,
      );
    }
  }

  const { summary } = report;
  lines.push('');
  lines.push(
    `Tested: ${summary.tested}  Passed: ${summary.passed}  Drifted: ${summary.drifted}  ` +
      `Skipped: ${summary.skipped}  Errors: ${summary.errors}  Warnings: ${summary.warnings}`,
  );
  if (summary.skipped > 0) {
    lines.push('Skipped operations are listed in the JSON report (--report).');
  }
  return lines.join('\n');
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

export function parseArgs(
  argv: string[],
  env: NodeJS.ProcessEnv = process.env,
): RunOptions & { reportFile?: string } {
  const baseUrlDefault = env.API_BASE_URL ?? 'http://localhost:3000';
  const options: RunOptions & { reportFile?: string } = {
    baseUrl: baseUrlDefault,
    specSource: '',
    token: env.API_TOKEN,
    apiKey: env.API_KEY,
    methods: ['get'],
    params: {},
    envelope: 'auto',
    strict: false,
    timeoutMs: 10000,
  };

  for (let i = 0; i < argv.length; i += 1) {
    const flag = argv[i];
    const next = (): string => {
      const value = argv[i + 1];
      if (value === undefined || value.startsWith('--'))
        throw new Error(`Missing value for ${flag}`);
      i += 1;
      return value;
    };

    switch (flag) {
      case '--base-url':
        options.baseUrl = next();
        break;
      case '--spec':
        options.specSource = next();
        break;
      case '--token':
        options.token = next();
        break;
      case '--api-key':
        options.apiKey = next();
        break;
      case '--param': {
        const pair = next();
        const separator = pair.indexOf('=');
        if (separator <= 0) throw new Error(`--param expects name=value (got "${pair}")`);
        options.params[pair.slice(0, separator)] = pair.slice(separator + 1);
        break;
      }
      case '--include':
        options.include = new RegExp(next());
        break;
      case '--exclude':
        options.exclude = new RegExp(next());
        break;
      case '--methods': {
        const methods = next()
          .split(',')
          .map((method) => method.trim().toLowerCase())
          .filter(Boolean);
        const invalid = methods.filter(
          (method) => !(HTTP_METHODS as readonly string[]).includes(method),
        );
        if (invalid.length > 0) throw new Error(`Unsupported method(s): ${invalid.join(', ')}`);
        options.methods = methods as HttpMethod[];
        break;
      }
      case '--envelope': {
        const mode = next();
        if (mode !== 'auto' && mode !== 'none')
          throw new Error('--envelope must be "auto" or "none"');
        options.envelope = mode;
        break;
      }
      case '--strict':
        options.strict = true;
        break;
      case '--timeout':
        options.timeoutMs = Number(next());
        if (!Number.isFinite(options.timeoutMs) || options.timeoutMs <= 0) {
          throw new Error('--timeout must be a positive number of milliseconds');
        }
        break;
      case '--report':
        options.reportFile = next();
        break;
      case '--help':
      case '-h':
        throw new HelpRequested();
      default:
        throw new Error(`Unknown option "${flag}"`);
    }
  }

  if (!options.specSource) {
    options.specSource = `${options.baseUrl.replace(/\/$/, '')}/api/openapi.json`;
  }
  return options;
}

class HelpRequested extends Error {}

async function main(): Promise<void> {
  let options: ReturnType<typeof parseArgs>;
  try {
    options = parseArgs(process.argv.slice(2));
  } catch (error) {
    if (error instanceof HelpRequested) {
      const source = fs.readFileSync(__filename, 'utf8');
      const header = source.slice(0, source.indexOf('*/') + 2);
      console.log(header);
      process.exit(0);
    }
    console.error(`Error: ${(error as Error).message}`);
    process.exit(2);
  }

  try {
    const spec = await loadSpec(options.specSource);
    const report = await runContractValidation(spec, options);
    console.log(formatReport(report));

    if (options.reportFile) {
      const target = path.resolve(options.reportFile);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, `${JSON.stringify(report, null, 2)}\n`);
      console.log(`Report written to ${target}`);
    }

    process.exit(report.summary.drifted > 0 ? 1 : 0);
  } catch (error) {
    console.error(`Fatal: ${(error as Error).message}`);
    process.exit(2);
  }
}

if (require.main === module) {
  void main();
}
